{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv'); cols=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
for c in cols:
 d=x[['yield_kg','farm',c]].dropna(); m=smf.ols(f'yield_kg ~ Q("{c}") + C(farm)',d).fit(); print(c, round(m.params.iloc[1],3), round(m.pvalues.iloc[1],5), round(m.rsquared,3))"}
